import type { ErrorRouteInput, ErrorRouteOutput } from '../../src/tools/error-route/contract.js';

export type ErrorRouteCase = { id: string; input: ErrorRouteInput; classification: ErrorRouteOutput['classification']; retry: ErrorRouteOutput['retry']; safe: boolean; clear: boolean };
const item = (id: string, status: number | undefined, body: string, classification: ErrorRouteCase['classification'], retry: ErrorRouteCase['retry'], safe: boolean, headers?: Record<string, string>, error?: string): ErrorRouteCase => ({
  id, input: { ...(status === undefined && !headers && !body ? {} : { response: { ...(status === undefined ? {} : { status }), ...(body ? { body } : {}), ...(headers ? { headers } : {}) } }), ...(error ? { error } : {}) }, classification, retry, safe, clear: true,
});
const baseTime = new Date('2026-01-01T00:00:00Z');
const retryDate = new Date(baseTime.getTime() + 30_000).toUTCString();

